#nullable enable // autogenerated

using System;
using PVZEngine;

namespace MVZ2.UI
{
    public static class NamespaceIDHelper
    {
        public static void ThrowIfNamespaceInvalid(this string spaceName)
        {
            if (!NamespaceID.ValidateNamespace(spaceName))
            {
                throw new FormatException($"Invalid namespace \"{spaceName}\".");
            }
        }
    }
}
